import type { PlayerConfig, SourceConfig } from "bitmovin-player";

export const playerConfig: PlayerConfig = {
  key: "YOUR_PLAYER_KEY",
  ui: false,
  playback: { autoplay: false, muted: true, audioLanguage: "en" },
  adaptation: {
    desktop: { bitrates: { maxSelectableVideoBitrate: "500kbps" } },
    mobile: { bitrates: { maxSelectableVideoBitrate: "500kbps" } },
  },
  buffer: {
    video: { forwardduration: 10 },
    audio: { forwardduration: 10 },
  },
  network: { defaultRequestTimeout: 5 },
};

export const sourceConfig: SourceConfig = {
  hls: "https://example.com/master.m3u8",
  title: "Configuration comparison",
  options: { startOffset: 5 },
};

onRecreate: (overrides) => {
  apiExplorer?.discardPatch("PlayerConfig", overrides);
  playerOverrides = deepMerge(playerOverrides, overrides);
  void build();
},
onReload: (srcOverrides) => {
  apiExplorer?.discardPatch("SourceConfig", srcOverrides);
  sourceOverrides = deepMerge(sourceOverrides, srcOverrides);
  currentSource = deepMerge(sourcePreset, sourceOverrides);
  if (player) void loadCurrentSource(player).catch((err: unknown) => console.error("config reload failed", err));
},
